from pathlib import Path


def read_inputs():
    cases = []
    deaths = []
    rows = Path("input/cases.csv").read_text(encoding="ascii").splitlines()
    for line in rows[1:]:
        _, count, dead = map(int, line.split(","))
        cases.append(count)
        deaths.append(dead)
    groups = []
    contacts = []
    for line in Path("input/population.txt").read_text(encoding="ascii").splitlines():
        kind, *values = line.split(" ")
        if kind == "group":
            groups.append((values[0], int(values[1]), float(values[2])))
        else:
            contacts.append(list(map(float, values)))
    interventions = []
    for line in Path("input/interventions.txt").read_text(encoding="ascii").splitlines():
        day, multiplier = line.split(" ")
        interventions.append((int(day), float(multiplier)))
    params = {"scenario": [], "contact_change": []}
    for line in Path("input/params.txt").read_text(encoding="ascii").splitlines():
        name, *values = line.split(" ")
        if name == "scenario":
            params[name].append((values[0], float(values[1])))
        elif name == "contact_change":
            params[name].append((values[0], values[1], float(values[2])))
        elif name in ("holdout", "death_lag", "generation", "horizon"):
            params[name] = int(values[0])
        elif name in ("milestones", "golden"):
            params[name] = tuple(map(int, values))
        elif name in ("beta_grid", "rho_grid"):
            params[name] = (float(values[0]), float(values[1]), int(values[2]))
        elif name == "nelder_mead":
            params[name] = (*map(float, values[:4]), int(values[4]))
        elif name in ("initial", "simplex"):
            params[name] = tuple(map(float, values))
        else:
            params[name] = float(values[0])
    return cases, deaths, groups, contacts, interventions, params


def write_outputs(outputs):
    folder = Path("output")
    folder.mkdir(parents=True, exist_ok=True)
    for name, lines in outputs.items():
        text = "\n".join(lines) + ("\n" if lines else "")
        (folder / name).write_text(text, encoding="ascii", newline="\n")

PHI = 0.6180339887498949


def golden(function, a, b, iterations):
    c = b - PHI * (b - a)
    d = a + PHI * (b - a)
    fc = function(c)
    fd = function(d)
    records = [(a, b, c, d, fc, fd)]
    for _ in range(iterations):
        if fc < fd:
            b, d, fd = d, c, fc
            c = b - PHI * (b - a)
            fc = function(c)
        else:
            a, c, fc = c, d, fd
            d = a + PHI * (b - a)
            fd = function(d)
        records.append((a, b, c, d, fc, fd))
    point, value = (c, fc) if fc < fd else (d, fd)
    return point, value, records


def nelder_mead(function, beta, gamma, delta_beta, delta_gamma,
                alpha, chi, psi, omega, iterations):
    vertices = []
    for number, point in enumerate(((beta, gamma), (beta + delta_beta, gamma),
                                    (beta, gamma + delta_gamma))):
        vertices.append((number, *point, function(*point)))
    initial = vertices.copy()
    serial = 3
    records = []

    def order(vertex):
        return vertex[3], vertex[0]

    def toward(origin, target, factor):
        return tuple(origin[axis] + factor * (target[axis] - origin[axis]) for axis in range(2))

    for _ in range(iterations):
        vertices.sort(key=order)
        first, second, third = vertices
        centroid = ((first[1] + second[1]) / 2.0, (first[2] + second[2]) / 2.0)
        reflected = tuple(centroid[axis] + alpha * (centroid[axis] - third[axis + 1])
                          for axis in range(2))
        fr = function(*reflected)
        accepted = None
        if fr < first[3]:
            expanded = toward(centroid, reflected, chi)
            fe = function(*expanded)
            if fe < fr:
                accepted, value, operation = expanded, fe, "expand"
            else:
                accepted, value, operation = reflected, fr, "reflect"
        elif fr < second[3]:
            accepted, value, operation = reflected, fr, "reflect"
        elif fr < third[3]:
            contracted = toward(centroid, reflected, psi)
            fc = function(*contracted)
            if fc <= fr:
                accepted, value, operation = contracted, fc, "contract_out"
        else:
            contracted = toward(centroid, third[1:3], psi)
            fc = function(*contracted)
            if fc < third[3]:
                accepted, value, operation = contracted, fc, "contract_in"
        if accepted is None:
            operation = "shrink"
            vertices = [first]
            for vertex in (second, third):
                point = toward(first[1:3], vertex[1:3], omega)
                vertices.append((serial, *point, function(*point)))
                serial += 1
        else:
            vertices = [first, second, (serial, *accepted, value)]
            serial += 1
        vertices.sort(key=order)
        records.append((operation, vertices[0]))
    return initial, records, vertices

def rk4_step(rates, state, multiplier):
    h = 0.25
    half = h / 2.0
    sixth = h / 6.0
    k1 = rates(state, multiplier)
    k2 = rates([a + half * p for a, p in zip(state, k1)], multiplier)
    k3 = rates([a + half * q for a, q in zip(state, k2)], multiplier)
    k4 = rates([a + h * r for a, r in zip(state, k3)], multiplier)
    return [a + sixth * (((p + 2.0 * q) + 2.0 * r) + s)
            for a, p, q, r, s in zip(state, k1, k2, k3, k4)]


def simulate(rates, initial, multipliers, inflows):
    state = list(initial)
    daily = []
    for multiplier in multipliers:
        for index in inflows:
            state[index] = 0.0
        for _ in range(4):
            state = rk4_step(rates, state, multiplier)
        daily.append(tuple(state))
    return daily
